using System;
using System.Linq;
using System.Reflection;
using RoomLab.Native;
class Program {
 static void Check(bool b,string s){if(!b)throw new Exception(s);}
 static void Main(string[] args){var p=NativeProjectLoader.LoadFile(args.Length>0?args[0]:"Assets/StreamingAssets/RoomLabNative/Editor3/editor3-three-themes.zip");int n=0;foreach(var c in p.Courses)foreach(var r in c.Rooms){var g=new NativeMotion(p,c.Id,r.Id,NativeGameplayRules.DemoPhysics);foreach(var o in r.Objects.Where(o=>o.Type.StartsWith("calculus.")||o.Type.StartsWith("slacker."))){var state=g.ObjectStates[o.Id];g.Player.face=-1;typeof(NativeMotion).GetMethod("Fire",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(g,new object[]{o});if(o.Type.StartsWith("calculus.")){Check(state.fired,"fired");Check(g.VisualState(o)=="active","visual");foreach(var b in r.Movables.Where(b=>(string)b.Raw["padId"]==o.Id))Check(g.Movables[b.Id].anim!=null&&g.Movables[b.Id].anim.from==0&&g.Movables[b.Id].anim.to==1,"group 0 to 1");}if(o.Type=="slacker.checkin")Check(state.signIns==1,"count");if(o.Type=="slacker.awake")Check(state.boosts==1&&g.Player.vx==-o.Number("speed")&&g.Player.vy==-o.Number("lift"),"awake launch");Check(state.cooldown==o.Number("cooldown",1),"cooldown exact");int countBefore=state.signIns;typeof(NativeMotion).GetMethod("Fire",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(g,new object[]{o});Check(state.signIns==countBefore,"cooldown blocks retrigger");g.Checkpoint.state=g.CaptureRoom();var captured=g.Checkpoint.state.objects[o.Id];int signs=captured.signIns,boosts=captured.boosts;bool fired=captured.fired;state.signIns+=10;state.boosts+=10;Check(captured.signIns==signs&&captured.boosts==boosts,"snapshot aliases");g.RespawnRemaining=0;g.Retry();Check(g.ObjectStates[o.Id].signIns==signs&&g.ObjectStates[o.Id].boosts==boosts&&g.ObjectStates[o.Id].fired==fired,"retry state");var saved=g.ExportContinuation();var restored=NativeMotion.FromContinuation(p,saved,NativeGameplayRules.DemoPhysics);Check(restored.Course.Id==c.Id,"restored course");Check(restored.ObjectStates[o.Id].signIns==signs&&restored.ObjectStates[o.Id].boosts==boosts&&restored.ObjectStates[o.Id].fired==fired,"continuation state");n++;}}Console.WriteLine("THEME_PASS mechanisms="+n);}
}
